function toQueryString(params: Record<string, string | number | Array<string | number>>): string {
  const parts: string[] = [];
  for (const k in params) {
    const v = params[k];
    const push = (val: string|number) => parts.push(`${encodeURIComponent(k)}=${encodeURIComponent(String(val))}`);
    if (Array.isArray(v)) { for (const x of v) push(x); }
    else push(v);
  }
  return parts.join('&');
}
